--- clean/crates/crypto/circuits/src/group/inspection.rs
+++ overlay/crates/crypto/circuits/src/group/inspection.rs
@@ -0,0 +1,155 @@
+//! Bounded observation of the existing authorization-key subgroup constraint.
+use super::{Point, Scalar};
+use commonware_cryptography::zk::circuit::{CircuitIdx, Var};
+use std::{cell::RefCell, marker::PhantomData, rc::Rc};
+
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct Report {
+    /// p.x, p.y, q.x, q.y, d.
+    pub inputs: [CircuitIdx; 5],
+    pub curve: [CircuitIdx; 2],
+    /// before.x, before.y, after.x, after.y for three existing additions.
+    pub doubles: Vec<[CircuitIdx; 4]>,
+    pub spans: Vec<[usize; 2]>,
+    pub nonidentity: [CircuitIdx; 2],
+    pub nonidentity_product: CircuitIdx,
+}
+
+#[derive(Default)]
+struct Building {
+    inputs: Option<[Option<CircuitIdx>; 5]>,
+    curve: Vec<[Option<CircuitIdx>; 2]>,
+    doubles: Vec<[Option<CircuitIdx>; 4]>,
+    spans: Vec<[usize; 2]>,
+    nonidentity: Vec<[Option<CircuitIdx>; 2]>,
+    boundary: Option<usize>,
+    nonidentity_product: Option<CircuitIdx>,
+}
+
+struct State { active: Option<Building>, completed: Vec<Building> }
+thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+
+pub struct Capture { _thread: PhantomData<Rc<()>> }
+impl Drop for Capture { fn drop(&mut self) { STATE.with(|state| *state.borrow_mut() = None); } }
+pub fn begin() -> anyhow::Result<Capture> {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        anyhow::ensure!(state.is_none(), "nested AK subgroup capture");
+        *state = Some(State { active: None, completed: Vec::new() });
+        Ok(Capture { _thread: PhantomData })
+    })
+}
+
+pub struct Scope { _thread: PhantomData<Rc<()>> }
+impl Drop for Scope {
+    fn drop(&mut self) {
+        STATE.with(|state| {
+            if let Some(state) = state.borrow_mut().as_mut() {
+                if let Some(report) = state.active.take() {
+                    if state.completed.len() < 2 { state.completed.push(report); }
+                }
+            }
+        });
+    }
+}
+pub(crate) fn scope() -> Option<Scope> {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        let state = state.as_mut()?;
+        assert!(state.active.is_none(), "nested authorization subgroup scope");
+        state.active = Some(Building::default());
+        Some(Scope { _thread: PhantomData })
+    })
+}
+
+fn record(callback: impl FnOnce(&mut Building)) {
+    STATE.with(|state| {
+        if let Some(active) = state.borrow_mut().as_mut().and_then(|state| state.active.as_mut()) {
+            callback(active);
+        }
+    });
+}
+pub(super) fn record_inputs(p: &Point<Var<'_, Scalar>>, q: &Point<Var<'_, Scalar>>, d: &Var<'_, Scalar>) {
+    record(|report| {
+        assert!(report.inputs.is_none(), "duplicate subgroup inputs");
+        report.inputs = Some([p.x.inspect_circuit_idx(), p.y.inspect_circuit_idx(),
+            q.x.inspect_circuit_idx(), q.y.inspect_circuit_idx(), d.inspect_circuit_idx()]);
+    });
+}
+pub(super) fn record_curve(left: &Var<'_, Scalar>, right: &Var<'_, Scalar>) {
+    record(|report| if report.curve.len() < 2 {
+        let handles = [left.inspect_circuit_idx(), right.inspect_circuit_idx()];
+        report.boundary = node_end(handles);
+        report.curve.push(handles);
+    });
+}
+fn node_end(values: [Option<CircuitIdx>; 2]) -> Option<usize> {
+    match values {
+        [Some(CircuitIdx::Node(a)), Some(CircuitIdx::Node(b))] => Some(a.max(b) as usize + 1),
+        _ => None,
+    }
+}
+pub(super) fn record_double(before: &Point<Var<'_, Scalar>>, after: &Point<Var<'_, Scalar>>) {
+    record(|report| if report.doubles.len() < 4 {
+        let output = [after.x.inspect_circuit_idx(), after.y.inspect_circuit_idx()];
+        report.doubles.push([before.x.inspect_circuit_idx(), before.y.inspect_circuit_idx(), output[0], output[1]]);
+        if let (Some(start), Some(end)) = (report.boundary, node_end(output)) {
+            report.spans.push([start, end]);
+        }
+        report.boundary = node_end(output);
+    });
+}
+pub(super) fn record_nonidentity(value: &Var<'_, Scalar>, inverse: &Var<'_, Scalar>) {
+    record(|report| if report.nonidentity.len() < 2 {
+        report.nonidentity.push([value.inspect_circuit_idx(), inverse.inspect_circuit_idx()]);
+        // assert_equal pushes existing IDs only; the next Node is Var::inv's
+        // inverse*value product. Catalogue verifies that exact source shape.
+        report.nonidentity_product = report.boundary.and_then(|node| u32::try_from(node).ok()).map(CircuitIdx::Node);
+    });
+}
+fn required<const N: usize>(values: [Option<CircuitIdx>; N]) -> anyhow::Result<[CircuitIdx; N]> {
+    anyhow::ensure!(values.iter().all(Option::is_some), "native subgroup handle unsupported");
+    Ok(values.map(Option::unwrap))
+}
+pub fn take() -> anyhow::Result<Report> {
+    STATE.with(|state| {
+        let mut state = state.borrow_mut();
+        let state = state.as_mut().ok_or_else(|| anyhow::anyhow!("inactive subgroup capture"))?;
+        anyhow::ensure!(state.active.is_none() && state.completed.len() == 1,
+            "expected one completed authorization subgroup scope");
+        let building = state.completed.pop().unwrap();
+        anyhow::ensure!(building.curve.len() == 1 && building.doubles.len() == 3
+            && building.spans.len() == 3 && building.nonidentity.len() == 1,
+            "authorization subgroup shape changed");
+        anyhow::ensure!(building.spans.iter().all(|[start, end]| start < end && end - start <= 128),
+            "subgroup double source span exceeds 128");
+        let inputs = required(building.inputs.ok_or_else(|| anyhow::anyhow!("missing subgroup inputs"))?)?;
+        let curve = required(building.curve[0])?;
+        let doubles = building.doubles.into_iter().map(required).collect::<anyhow::Result<Vec<_>>>()?;
+        let nonidentity = required(building.nonidentity[0])?;
+        let nonidentity_product = building.nonidentity_product
+            .ok_or_else(|| anyhow::anyhow!("missing nonidentity product source boundary"))?;
+        anyhow::ensure!(doubles[0][..2] == inputs[2..4]
+            && doubles[1][..2] == doubles[0][2..] && doubles[2][..2] == doubles[1][2..]
+            && nonidentity[0] == inputs[0], "subgroup chain/consumer roles changed");
+        Ok(Report { inputs, curve, doubles, spans: building.spans, nonidentity, nonidentity_product })
+    })
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    #[test]
+    fn capture_scope_is_exclusive_and_cleans_up() {
+        assert!(scope().is_none());
+        { let _capture = begin().unwrap(); assert!(begin().is_err());
+          { let _scope = scope().unwrap(); assert!(take().is_err()); }
+          assert!(take().is_err()); }
+        let failed = std::panic::catch_unwind(|| {
+            let _capture = begin().unwrap(); let _scope = scope().unwrap(); panic!("synthetic AK failure");
+        });
+        assert!(failed.is_err());
+        { let _capture = begin().unwrap(); assert!(take().is_err()); }
+        assert!(scope().is_none());
+    }
+}
